def _sql_literal(v: Any) -> str:
    if v is None:
        return "NULL"
    if isinstance(v, bool):
        return "TRUE" if v else "FALSE"
    if isinstance(v, float):
        return repr(v) if math.isfinite(v) else f"'{v}'::float"   # 'nan' / 'inf' / '-inf'
    if isinstance(v, int):
        return str(v)
    return "'" + str(v).replace("'", "''") + "'"


