def fix_absolute(s):
    # from app.X import ... / from app import X, Y
    def mod(m):
        name = m.group(1)
        return f"from app.{pkg[name]}.{name} import" if name in pkg else m.group(0)
    s = re.sub(r"from app\.(\w+) import", mod, s)
    def multi(m):
        names = [n.strip() for n in m.group(1).split(",")]
        groups = {}
        for n in names:
            base = n.split(" as ")[0].strip()
            groups.setdefault(pkg.get(base, ""), []).append(n)
        out = []
        for g, ns in groups.items():
            out.append(f"from app{'.'+g if g else ''} import {', '.join(ns)}")
        return "\n".join(out)
    s = re.sub(r"from app import ([^\n(]+)", multi, s)
    s = s.replace('"app.config.gemini_disabled"', '"app.ai.config.gemini_disabled"')
    return s

